<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),router=useRouter(),mode=ref<'login'|'register'>('login'),loading=ref(false),error=ref(''),form=ref({email:'',password:'',displayName:''});async function submit(){loading.value=true;error.value='';try{if(mode.value==='login')await auth.login(form.value.email,form.value.password);else await auth.register(form.value.email,form.value.password,form.value.displayName);router.push('/')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}</script>
<template><div class="auth-page"><section class="auth-brand"><div class="brand-mark">CO</div><span>CAREER ORBIT</span><h1>把每一次练习，<br/>变成更接近 Offer 的证据。</h1><p>真实简历、真实知识检索、真实模型评价。没有虚构分数，也没有预置面试结论。</p><div><i/>RAG 服务和模型配置由系统管理员维护</div></section><section class="auth-form"><div class="login-card"><small>WELCOME TO CAREER ORBIT</small><h2>{{mode==='login'?'登录你的账户':'创建求职档案'}}</h2><p>{{mode==='login'?'继续上一次训练进度':'从一份真实简历开始'}}</p><form @submit.prevent="submit"><label v-if="mode==='register'">姓名<input v-model="form.displayName" required autocomplete="name" placeholder="你的姓名"/></label><label>邮箱<input v-model="form.email" required autocomplete="email" type="email" placeholder="name@example.com"/></label><label>密码<input v-model="form.password" required minlength="8" :autocomplete="mode==='login'?'current-password':'new-password'" type="password" placeholder="至少 8 位"/></label><div v-if="error" class="error-box">{{error}}</div><button class="primary-button" :disabled="loading">{{loading?'处理中…':mode==='login'?'登录':'注册并登录'}}</button></form><button class="mode-link" @click="mode=mode==='login'?'register':'login'">{{mode==='login'?'没有账户？立即注册':'已有账户？返回登录'}}</button></div></section></div></template>
<style scoped>.auth-page{min-height:100vh;display:grid;grid-template-columns:1.1fr .9fr;background:#101513;color:white}.auth-brand{padding:65px 8vw;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;background:radial-gradient(circle at 80% 20%,#d5eb5520,transparent 35%)}.auth-brand>span{letter-spacing:3px;font-size:11px;margin-top:18px}.auth-brand h1{font-size:44px;line-height:1.35;letter-spacing:-2px;margin:45px 0 20px}.auth-brand p{color:#949e99;max-width:530px;line-height:1.8}.auth-brand>div:last-child{margin-top:35px;font-size:10px;color:#89938e}.auth-brand i{display:inline-block;width:6px;height:6px;background:var(--lime);border-radius:50%;margin-right:8px}.auth-form{background:#f2f1eb;color:#18201c;display:grid;place-items:center}.login-card{width:390px}.login-card>small{letter-spacing:2px;color:#929994}.login-card h2{font-size:30px;margin:15px 0 5px}.login-card>p{color:#858d88;font-size:12px}.login-card form{margin-top:30px}.login-card label{display:flex;flex-direction:column;gap:7px;font-size:10px;font-weight:700;margin-bottom:16px}.login-card input{height:46px;border:1px solid #d5d8d0;background:#faf9f5;border-radius:10px;padding:0 13px;outline:none}.login-card form>.primary-button{width:100%;justify-content:center;height:46px}.mode-link{width:100%;border:0;background:none;color:var(--orange);font-size:10px;margin-top:16px;cursor:pointer}.error-box{background:#f9ded5;color:#a43f22;padding:10px;border-radius:8px;font-size:10px;margin-bottom:12px}</style>
